export const MANUAL: Record<Lang, ManualContent> = { en, ru, es, uk };

// ---- Modules that ship dark --------------------------------------------------
// A module that is off (constants/modules.ts) has no screen, so the manual must
// not describe one. Keyed by the ENGLISH title, like the help buttons; `from`
// hides only the paragraphs from that position on, for a module that extends an
// existing section (crew certificates in Certificates). The order and length of
// each section's body are the same in every language.
const MODULE_PARTS: { title: string; module: ModuleKey; from?: number; drop?: number[] }[] = [
  { title: 'Certificates', module: 'crewCerts', from: 5 },
  { title: 'Certificates', module: 'serviceReport', drop: [4] },
  { title: 'Access — which tabs each device shows', module: 'access' },
  { title: 'Hours of rest', module: 'rest' },
  { title: 'Crew list and certificate matrix', module: 'crewCerts' },
  { title: 'Planned maintenance', module: 'pms' },
  { title: 'Spare parts', module: 'spares' },
  { title: 'Confirmed signatures', module: 'signConfirm' },
  { title: 'ISM documents', module: 'docs' },
  { title: 'Permits to work and risk assessments', module: 'ptw' },
  { title: 'Fuel', module: 'fuel' },
  { title: 'Garbage Record Book', module: 'garbage' },
  { title: 'Inspection rounds', module: 'rounds' },
  { title: 'Oil Record Book', module: 'orb' },
  { title: 'Sewage record', module: 'sewage' },
  { title: 'Ballast water', module: 'ballast' },
  { title: 'SOPEP', module: 'sopep' },
  { title: 'Board', module: 'board' },
  { title: 'Surveys & audits', module: 'surveys' },
  { title: 'Inspection readiness', module: 'readiness' },
  { title: 'Dynamic positioning', module: 'dp' },
  { title: 'Bridge and engine checklists', module: 'watchChecks' },
  { title: 'Security (ISPS)', module: 'security' },
  // Paragraphs of a live section about a page that ships dark (15 Oct 2026).
  { title: 'Security (ISPS)', module: 'searches', drop: [6] },
  { title: 'Security (ISPS)', module: 'ssp', drop: [7] },
  { title: 'Security (ISPS)', module: 'patrols', drop: [8] },
  { title: 'Security (ISPS)', module: 'keys', drop: [9] },
  { title: 'Hospital', module: 'hospital' },
  { title: 'Passengers', module: 'passengers' },
  { title: 'Stores', module: 'stores' },
  { title: 'AI assistant', module: 'ai' },
  { title: 'Monthly safety meeting', module: 'meetings' },
  { title: 'Drills', module: 'drills' },
  { title: 'Safety observations & NC', module: 'qhse' },
  { title: 'Fleet console (superintendent)', module: 'fleet' },
];

/** The manual as this build should show it: sections of switched-off modules removed. */
export function releasedManual(lang: Lang): ManualContent {
  const content = MANUAL[lang];
  const sections: Section[] = [];
  content.sections.forEach((sec, i) => {
    const off = MODULE_PARTS.filter((p) => p.title === MANUAL.en.sections[i]?.title && !moduleOn(p.module));
    if (off.some((p) => p.from == null && !p.drop)) return; // the whole section's module is off
    const from = Math.min(...off.filter((p) => p.from != null).map((p) => p.from!), Infinity);
    const drop = new Set(off.flatMap((p) => p.drop ?? []));
    if (!off.length) sections.push(sec);
    else sections.push({ ...sec, body: sec.body?.slice(0, from === Infinity ? undefined : from).filter((_, k) => !drop.has(k)) });
  });
  return { ...content, sections };
}
